sp_widget.client_script:
api.controller=function() {
  var c = this;
  c.data = { ok: false, summary: null, trend: [], topGaps: [] };
  c.serverAction = 'load';
};

sp_widget.script_server:
(function() {
  data.appScope = input.app_scope || $sp.getParameter('app_scope') || '';
  if (!data.appScope) {
    data.ok = false;
    return;
  }
  try {
    var engine = new x_snc_testreach.TestReachRiskEngine();
    var dashboard = engine.getDashboardData(data.appScope);
    data.ok = true;
    data.summary = dashboard.summary;
    data.risk = dashboard.risk;
    data.trend = dashboard.trend;
    data.topGaps = dashboard.gaps.slice(0, 10);
  } catch (e) {
    data.ok = false;
    data.error = e.message;
  }
})();
